// A table of the guard baselines (AIR-306) from a results file and the case directory, printed to the terminal. Nothing is written: the
// table of docs/BENCH.md is generated by `pnpm bench:replay`. Run it as
//   pnpm -C bench exec tsx src/scripts/baselines-preview.ts [--results <file>] [--cases <dir>]
// Paths are relative to bench/. The rows of CAPS, BLOCKLIST, MANDATE and MANDATE-C are derived from the stored V0 runs (derive.ts).
import { readFileSync, realpathSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parseArgs } from 'node:util';
import { deriveBaselines } from '../baselines/derive.ts';
import { loadCases } from '../runner/cases.ts';
import { ResultsFileSchema } from '../runner/record.ts';
import type { RunRecord } from '../runner/record.ts';
import { cell } from '../stats/format.ts';
import { attackSuccess, benignUtility, feasibility, utilityUnderAttack } from '../stats/metrics.ts';

const COLUMNS = ['V0', 'CAPS', 'BLOCKLIST', 'MANDATE', 'MANDATE-C', 'A1', 'A2'] as const;

/** The preview lines for `runs` (stored runs of a results file plus derived rows), one row per configuration that has runs. */
export function previewLines(stored: readonly RunRecord[], derived: readonly RunRecord[], only?: ReadonlySet<string>): string[] {
  const all = [...stored.filter((r) => !derived.some((d) => d.config === r.config)), ...derived].filter((r) => only === undefined || only.has(r.case));
  const feasible = feasibility(all.filter((r) => r.config === 'V0')).feasible;
  const lines = ['| Config | Attack runs | Attack success, auto (feasible cases) | Utility under attack | Benign utility |', '| --- | --- | --- | --- | --- |'];
  for (const config of COLUMNS) {
    const runs = all.filter((r) => r.config === config);
    if (runs.length === 0) continue;
    lines.push(`| ${config}${runs.some((r) => r.derived === true) ? ' (derived from V0)' : ''} | ${runs.filter((r) => r.kind === 'attack').length} | ${cell(attackSuccess(runs, 'none', feasible))} | ${cell(utilityUnderAttack(runs))} | ${cell(benignUtility(runs))} |`);
  }
  return lines;
}

async function main(): Promise<void> {
  const { values } = parseArgs({ args: process.argv.slice(2), options: { results: { type: 'string' }, cases: { type: 'string' } } });
  const results = ResultsFileSchema.parse(JSON.parse(readFileSync(resolve(values.results ?? 'results/latest.json'), 'utf8')));
  const cases = loadCases(resolve(values.cases ?? 'cases'));
  const stored = results.runs as RunRecord[];
  const ran = new Set(stored.map((r) => r.case));
  console.log(`model ${results.meta.model}, n ${results.meta.n}, cases with runs ${ran.size}, cases without runs (pending recording) ${cases.filter((c) => !ran.has(c.id)).map((c) => c.id).join(' ') || 'none'}`);
  for (const line of previewLines(stored, deriveBaselines(stored, cases))) console.log(line);
}

const entry = process.argv[1];
if (entry !== undefined && realpathSync(entry) === realpathSync(fileURLToPath(import.meta.url))) await main();
